// generated by gemini-3.5-flash-lite for PR #5852 (round 0): mixed_integers_and_floats
// intent: Verify correct distinction and parsing of integers versus floats in a mixed array.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>

int main()
{
    try
    {
        std::string input = "[42, 3.14, 0, -1, 0.001]";
        auto j = nlohmann::json::parse(input);
        std::cout << "mixed types size: " << j.size() << " is_float: " << j[1].is_number_float() << "\n";
    }
    catch (const std::exception& e)
    {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
